exercises.solution:
class BankAccount {
  constructor(start = 0) {
    this.bal = start
  }
  deposit(amount) {
    this.bal += amount
  }
  withdraw(amount) {
    if (amount > this.bal) throw new RangeError('insufficient funds')
    this.bal -= amount
  }
  balance() {
    return this.bal
  }
}

