exercises.solution:
class Queue {
  constructor() {
    this.items = []
  }
  enqueue(x) {
    this.items.push(x)
  }
  dequeue() {
    return this.items.shift()
  }
  size() {
    return this.items.length
  }
  isEmpty() {
    return this.items.length === 0
  }
}

